import sys

import numpy as np
import wgpu

SHADER = """
struct Params { width: u32, height: u32 };

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(8, 8)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }
    var n: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy = dy + 1) {
        for (var dx: i32 = -1; dx <= 1; dx = dx + 1) {
            if (dx == 0 && dy == 0) {
                continue;
            }
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx < 0 || ny < 0 || nx >= i32(params.width) || ny >= i32(params.height)) {
                continue;
            }
            n = n + src[u32(ny) * params.width + u32(nx)];
        }
    }
    let i = y * params.width + x;
    let alive = src[i] == 1u;
    var next: u32 = 0u;
    if (n == 3u || (alive && n == 2u)) {
        next = 1u;
    }
    dst[i] = next;
}
"""


def parse(path):
    with open(path) as f:
        tokens = f.read().split()
    width, height, generations = int(tokens[0]), int(tokens[1]), int(tokens[2])
    digits = "".join(tokens[3:])
    cells = np.zeros(width * height, dtype=np.uint32)
    vals = np.frombuffer(digits[: width * height].encode(), dtype=np.uint8) - ord("0")
    cells[: len(vals)] = vals
    return width, height, generations, cells


def run_gpu(width, height, generations, cells):
    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()
    size = width * height * 4
    usage = wgpu.BufferUsage.STORAGE | wgpu.BufferUsage.COPY_SRC | wgpu.BufferUsage.COPY_DST
    bufs = [device.create_buffer(size=size, usage=usage) for _ in range(2)]
    params = device.create_buffer(
        size=16, usage=wgpu.BufferUsage.UNIFORM | wgpu.BufferUsage.COPY_DST
    )
    device.queue.write_buffer(bufs[0], 0, cells.tobytes())
    device.queue.write_buffer(
        params, 0, np.array([width, height, 0, 0], dtype=np.uint32).tobytes()
    )

    if generations == 0:
        return device.queue.read_buffer(bufs[0])

    module = device.create_shader_module(code=SHADER)
    pipeline = device.create_compute_pipeline(
        layout="auto", compute={"module": module, "entry_point": "main"}
    )
    layout = pipeline.get_bind_group_layout(0)
    groups = [
        device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": params, "offset": 0, "size": 16}},
                {"binding": 1, "resource": {"buffer": bufs[i], "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": bufs[1 - i], "offset": 0, "size": size}},
            ],
        )
        for i in range(2)
    ]
    gx, gy = (width + 7) // 8, (height + 7) // 8
    # Submit in batches to keep command buffers modest.
    done = 0
    while done < generations:
        batch = min(100, generations - done)
        enc = device.create_command_encoder()
        cp = enc.begin_compute_pass()
        cp.set_pipeline(pipeline)
        for g in range(done, done + batch):
            cp.set_bind_group(0, groups[g % 2])
            cp.dispatch_workgroups(gx, gy, 1)
        cp.end()
        device.queue.submit([enc.finish()])
        done += batch
    return device.queue.read_buffer(bufs[generations % 2])


def main():
    width, height, generations, cells = parse(sys.argv[1])
    raw = run_gpu(width, height, generations, cells)
    grid = np.frombuffer(raw, dtype=np.uint32)[: width * height].reshape(height, width)
    lines = [" ".join(str(int(v)) for v in row) for row in grid]
    lines.append(f"ALIVE {int(grid.sum())}")
    sys.stdout.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
